const float B3[1] = {0.333239f};


float AI_Agirlik_Tahmin(uint32_t ham_adc) {
    float input = ((float)ham_adc - MIN_ADC) / (MAX_ADC - MIN_ADC);
    if(input < 0.0f) input = 0.0f;
    if(input > 1.0f) input = 1.0f;

    // Katman 1: (Dense 1 -> 32 Nöron)
    float layer1_out[32];
    for(int i = 0; i < 32; i++) {
        float val = input * W1[i] + B1[i];
        layer1_out[i] = (val > 0.0f) ? val : val * 0.100000f;
    }

    // Katman 2: (Dense 32 -> 16 Nöron Row-Major Eşleme: W2[j * 16 + i])
    float layer2_out[16];
    for(int i = 0; i < 16; i++) {
        float sum = 0.0f;
        for(int j = 0; j < 32; j++) {
            sum += layer1_out[j] * W2[j * 16 + i]; 
        }
        float val = sum + B2[i];
        layer2_out[i] = (val > 0.0f) ? val : val * 0.100000f;
    }

    // Çıkış Katmanı: (Dense 16 -> 1 Nöron)
    float nihai_kg = 0.0f;
    for(int i = 0; i < 16; i++) {
        nihai_kg += layer2_out[i] * W3[i];
    }
    nihai_kg += B3[0];

    if(nihai_kg < 0.0f) nihai_kg = 0.0f;
    return nihai_kg;
}
